import React, { useState, useEffect } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import axios from "axios";

const AdmEditAluno = ({ alunoId, onClose }) => {
  const [aluno, setAluno] = useState({
    nome: "",
    email: "",
    morada: "",
    contacto: "",
    cursos: [],
  });

  useEffect(() => {
    const fetchAluno = async () => {
      try {
        const response = await axios.get(`/api/alunos/${alunoId}`);
        setAluno(response.data);
      } catch (error) {
        console.error("Erro ao buscar aluno:", error);
      }
    };

    fetchAluno();
  }, [alunoId]);

  const handleChange = (e) =>
    setAluno({ ...aluno, [e.target.name]: e.target.value });

  const handleCursoChange = (index, value) => {
    const novosCursos = [...aluno.cursos];
    novosCursos[index] = value;
    setAluno({ ...aluno, cursos: novosCursos });
  };

  const handleAddCurso = () =>
    setAluno({ ...aluno, cursos: [...aluno.cursos, ""] });

  const handleSave = async () => {
    try {
      await axios.put(`/api/alunos/${alunoId}`, aluno);
      alert("Aluno atualizado com sucesso!");
      onClose();
    } catch (error) {
      console.error("Erro ao salvar aluno:", error);
    }
  };

  return (
    <div className="container mt-4">
      <h2 className="text-center">Editar Aluno</h2>

      <div className="mb-3">
        <label className="form-label">Nome</label>
        <input
          type="text"
          className="form-control"
          name="nome"
          value={aluno.nome}
          onChange={handleChange}
        />
      </div>

      <div className="mb-3">
        <label className="form-label">Email</label>
        <input
          type="email"
          className="form-control"
          name="email"
          value={aluno.email}
          onChange={handleChange}
        />
      </div>

      <div className="mb-3">
        <label className="form-label">Morada</label>
        <input
          type="text"
          className="form-control"
          name="morada"
          value={aluno.morada}
          onChange={handleChange}
        />
      </div>

      <div className="mb-3">
        <label className="form-label">Contacto</label>
        <input
          type="text"
          className="form-control"
          name="contacto"
          value={aluno.contacto}
          onChange={handleChange}
        />
      </div>

      <label className="form-label">Cursos</label>
      {aluno.cursos.map((curso, index) => (
        <div key={index} className="input-group mb-2">
          <input
            type="text"
            className="form-control"
            value={curso}
            onChange={(e) => handleCursoChange(index, e.target.value)}
          />
        </div>
      ))}
      <button
        className="btn btn-outline-secondary mb-3"
        onClick={handleAddCurso}
      >
        + Adicionar Curso
      </button>

      <div className="d-flex justify-content-between">
        <button className="btn btn-danger" onClick={onClose}>
          Cancelar
        </button>
        <button className="btn btn-primary" onClick={handleSave}>
          Salvar
        </button>
      </div>
    </div>
  );
};

export default AdmEditAluno;
